#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <openssl/evp.h>

static EVP_CIPHER_CTX *g_ctx = NULL;

static PyObject *encrypt(PyObject *self, PyObject *args) {
    Py_buffer key, nonce, pt, aad;
    int has_aad = 0;
    if (!PyArg_ParseTuple(args, "y*y*y*|y*", &key, &nonce, &pt, &aad)) {
        /* try without aad? ParseTuple with | should allow missing */
        return NULL;
    }
    /* If aad not provided, PyArg_ParseTuple with | leaves it uninitialized if we don't init.
       We used y* which requires init. Let's handle differently. */
    PyBuffer_Release(&key);
    PyBuffer_Release(&nonce);
    PyBuffer_Release(&pt);
    PyBuffer_Release(&aad);
    PyErr_SetString(PyExc_RuntimeError, "unreachable");
    return NULL;
}

/* Proper implementation */
static PyObject *aesgcm_encrypt(PyObject *self, PyObject *args) {
    PyObject *key_obj, *nonce_obj, *pt_obj, *aad_obj = Py_None;
    if (!PyArg_ParseTuple(args, "OOO|O", &key_obj, &nonce_obj, &pt_obj, &aad_obj))
        return NULL;

    Py_buffer key, nonce, pt, aad;
    memset(&aad, 0, sizeof(aad));
    if (PyObject_GetBuffer(key_obj, &key, PyBUF_SIMPLE) != 0) return NULL;
    if (PyObject_GetBuffer(nonce_obj, &nonce, PyBUF_SIMPLE) != 0) { PyBuffer_Release(&key); return NULL; }
    if (PyObject_GetBuffer(pt_obj, &pt, PyBUF_SIMPLE) != 0) { PyBuffer_Release(&key); PyBuffer_Release(&nonce); return NULL; }

    int have_aad = 0;
    if (aad_obj != Py_None && aad_obj != NULL) {
        if (PyObject_GetBuffer(aad_obj, &aad, PyBUF_SIMPLE) != 0) {
            PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);
            return NULL;
        }
        have_aad = aad.len > 0;
    }

    const EVP_CIPHER *cipher = NULL;
    if (key.len == 16) cipher = EVP_aes_128_gcm();
    else if (key.len == 24) cipher = EVP_aes_192_gcm();
    else if (key.len == 32) cipher = EVP_aes_256_gcm();
    else {
        PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);
        if (have_aad || aad.buf) PyBuffer_Release(&aad);
        PyErr_SetString(PyExc_ValueError, "invalid key size");
        return NULL;
    }

    if (!g_ctx) g_ctx = EVP_CIPHER_CTX_new();
    EVP_CIPHER_CTX *ctx = g_ctx;

    PyObject *ct = PyBytes_FromStringAndSize(NULL, pt.len);
    if (!ct) goto fail;
    unsigned char *out = (unsigned char *)PyBytes_AS_STRING(ct);
    unsigned char tag[16];
    int outlen = 0;

    if (EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL) != 1) goto fail_ct;
    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, (int)nonce.len, NULL) != 1) goto fail_ct;
    if (EVP_EncryptInit_ex(ctx, NULL, NULL, key.buf, nonce.buf) != 1) goto fail_ct;
    if (have_aad) {
        if (EVP_EncryptUpdate(ctx, NULL, &outlen, aad.buf, (int)aad.len) != 1) goto fail_ct;
    }
    if (pt.len > 0) {
        if (EVP_EncryptUpdate(ctx, out, &outlen, pt.buf, (int)pt.len) != 1) goto fail_ct;
    }
    if (EVP_EncryptFinal_ex(ctx, out + outlen, &outlen) != 1) goto fail_ct;
    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag) != 1) goto fail_ct;

    PyObject *tag_obj = PyBytes_FromStringAndSize((const char *)tag, 16);
    if (!tag_obj) goto fail_ct;

    PyBuffer_Release(&key);
    PyBuffer_Release(&nonce);
    PyBuffer_Release(&pt);
    if (aad.buf) PyBuffer_Release(&aad);

    return Py_BuildValue("NN", ct, tag_obj);

fail_ct:
    Py_DECREF(ct);
fail:
    PyBuffer_Release(&key);
    PyBuffer_Release(&nonce);
    PyBuffer_Release(&pt);
    if (aad.buf) PyBuffer_Release(&aad);
    if (!PyErr_Occurred())
        PyErr_SetString(PyExc_RuntimeError, "openssl encrypt failed");
    return NULL;
}

static PyMethodDef methods[] = {
    {"encrypt", aesgcm_encrypt, METH_VARARGS, "AES-GCM encrypt"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "aesgcm_fast", NULL, -1, methods
};

PyMODINIT_FUNC PyInit_aesgcm_fast(void) {
    return PyModule_Create(&moduledef);
}
