#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <openssl/evp.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

static uint8_t *counters;
static uint8_t *ks;
static uint8_t key[16];
static int nblocks;
static int nthreads;

typedef struct { int tid; int start; int end; EVP_CIPHER_CTX *ctx; } job_t;

void *worker(void *arg) {
    job_t *j = arg;
    int outlen = 0;
    EVP_EncryptUpdate(j->ctx, ks + j->start * 16, &outlen,
                      counters + j->start * 16, (j->end - j->start) * 16);
    return NULL;
}

int main() {
    nblocks = 60000 * 1024 / 16; /* 3,840,000 */
    nthreads = 6;
    counters = malloc((size_t)nblocks * 16);
    ks = malloc((size_t)nblocks * 16);
    FILE *f = fopen("/dev/urandom", "rb");
    fread(key, 1, 16, f);
    uint8_t nonce[12];
    fread(nonce, 1, 12, f);
    fclose(f);

    double t0 = now();
    for (int i = 0; i < nblocks; i++) {
        uint8_t *b = counters + (size_t)i * 16;
        memcpy(b, nonce, 12);
        uint32_t ctr = (uint32_t)(i + 2);
        b[12] = ctr >> 24; b[13] = ctr >> 16; b[14] = ctr >> 8; b[15] = ctr;
    }
    double t1 = now();
    printf("build counters: %.2f ms\n", (t1-t0)*1000);

    EVP_CIPHER_CTX *ctxs[16];
    for (int i = 0; i < nthreads; i++) {
        ctxs[i] = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(ctxs[i], EVP_aes_128_ecb(), NULL, key, NULL);
        EVP_CIPHER_CTX_set_padding(ctxs[i], 0);
    }

    /* sequential */
    t0 = now();
    int outlen = 0;
    EVP_EncryptUpdate(ctxs[0], ks, &outlen, counters, nblocks * 16);
    t1 = now();
    printf("seq ECB: %.2f ms\n", (t1-t0)*1000);

    /* parallel */
    int chunk = nblocks / nthreads;
    pthread_t th[16];
    job_t jobs[16];
    t0 = now();
    for (int i = 0; i < nthreads; i++) {
        jobs[i].tid = i;
        jobs[i].start = i * chunk;
        jobs[i].end = (i == nthreads-1) ? nblocks : (i+1)*chunk;
        jobs[i].ctx = ctxs[i];
        pthread_create(&th[i], NULL, worker, &jobs[i]);
    }
    for (int i = 0; i < nthreads; i++) pthread_join(th[i], NULL);
    t1 = now();
    printf("par ECB %d threads: %.2f ms\n", nthreads, (t1-t0)*1000);

    /* parallel again to see steady */
    t0 = now();
    for (int rep = 0; rep < 3; rep++) {
        for (int i = 0; i < nthreads; i++) pthread_create(&th[i], NULL, worker, &jobs[i]);
        for (int i = 0; i < nthreads; i++) pthread_join(th[i], NULL);
    }
    t1 = now();
    printf("par ECB avg: %.2f ms\n", (t1-t0)/3*1000);
    return 0;
}
