{"command":"cat > ./_aesbuild/bench_ghash.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <openssl/evp.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

/* Use OpenSSL GCM on chunks to measure GHASH-dominated? Or use EVP_CIPHER with AES-GCM full.
   We want GHASH speed. OpenSSL exposes CRYPTO_gcm128_... only internally.
   Alternative: time AES-GCM minus AES-CTR to estimate GHASH.
*/

int main() {
    int n = 60000 * 1024;
    uint8_t *pt = malloc(n);
    uint8_t *out = malloc(n + 16);
    uint8_t key[16], nonce[12];
    FILE *f = fopen("/dev/urandom", "rb");
    fread(pt, 1, n, f);
    fread(key, 1, 16, f);
    fread(nonce, 1, 12, f);
    fclose(f);

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int outlen, tmplen;
    unsigned char tag[16];

    /* warmup */
    EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
    EVP_EncryptUpdate(ctx, out, &outlen, pt, n);
    EVP_EncryptFinal_ex(ctx, out + outlen, &tmplen);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);

    double t0 = now();
    int reps = 5;
    for (int i = 0; i < reps; i++) {
        EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        EVP_EncryptUpdate(ctx, out, &outlen, pt, n);
        EVP_EncryptFinal_ex(ctx, out + outlen, &tmplen);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
    }
    double t1 = now();
    printf("AES-GCM full: %.2f ms\n", (t1-t0)/reps*1000);

    /* CTR */
    uint8_t iv[16];
    memcpy(iv, nonce, 12);
    iv[12]=0; iv[13]=0; iv[14]=0; iv[15]=2;
    EVP_CIPHER_CTX *c2 = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(c2, EVP_aes_128_ctr(), NULL, key, iv);
    EVP_EncryptUpdate(c2, out, &outlen, pt, n);
    t0 = now();
    for (int i = 0; i < reps; i++) {
        /* reinit counter */
        memcpy(iv, nonce, 12);
        iv[12]=0; iv[13]=0; iv[14]=0; iv[15]=2;
        EVP_EncryptInit_ex(c2, NULL, NULL, key, iv);
        EVP_EncryptUpdate(c2, out, &outlen, pt, n);
    }
    t1 = now();
    printf("AES-CTR: %.2f ms\n", (t1-t0)/reps*1000);

    /* in-place CTR */
    t0 = now();
    for (int i = 0; i < reps; i++) {
        memcpy(iv, nonce, 12);
        iv[12]=0; iv[13]=0; iv[14]=0; iv[15]=2;
        EVP_EncryptInit_ex(c2, NULL, NULL, key, iv);
        EVP_EncryptUpdate(c2, pt, &outlen, pt, n); /* encrypt in place then it's ciphertext; next iter wrong but timing ok */
    }
    t1 = now();
    printf("AES-CTR in-place (corrupts): %.2f ms\n", (t1-t0)/reps*1000);

    printf("implied GHASH ~= GCM - CTR\n");
    return 0;
}
EOF
