{"command":"cat > ./_aesbuild/bench_par_gcm.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <openssl/evp.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

static uint8_t *pt, *out, key[16], nonce[12];
static int n, nthreads;

typedef struct { int tid; int start; int len; } job_t;

void *worker(void *arg) {
    job_t *j = arg;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int outlen, tmplen;
    unsigned char tag[16];
    /* unique nonce per chunk: use original nonce but XOR tid into last byte — just for timing */
    uint8_t iv[12];
    memcpy(iv, nonce, 12);
    iv[11] ^= j->tid;
    EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
    EVP_EncryptUpdate(ctx, out + j->start, &outlen, pt + j->start, j->len);
    EVP_EncryptFinal_ex(ctx, out + j->start + outlen, &tmplen);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}

int main() {
    n = 60000 * 1024;
    nthreads = 6;
    pt = malloc(n);
    out = malloc(n);
    FILE *f = fopen("/dev/urandom", "rb");
    fread(pt, 1, n, f); fread(key, 1, 16, f); fread(nonce, 1, 12, f); fclose(f);

    int chunk = n / nthreads;
    pthread_t th[16];
    job_t jobs[16];
    for (int i = 0; i < nthreads; i++) {
        jobs[i].tid = i;
        jobs[i].start = i * chunk;
        jobs[i].len = (i == nthreads-1) ? n - i*chunk : chunk;
    }
    /* warmup */
    for (int i = 0; i < nthreads; i++) pthread_create(&th[i], NULL, worker, &jobs[i]);
    for (int i = 0; i < nthreads; i++) pthread_join(th[i], NULL);

    double t0 = now();
    int reps = 5;
    for (int r = 0; r < reps; r++) {
        for (int i = 0; i < nthreads; i++) pthread_create(&th[i], NULL, worker, &jobs[i]);
        for (int i = 0; i < nthreads; i++) pthread_join(th[i], NULL);
    }
    double t1 = now();
    printf("par independent GCM %d thr: %.2f ms\n", nthreads, (t1-t0)/reps*1000);

    /* reuse contexts */
    return 0;
}
EOF
