    tmp8=_mm_srli_si128(tmp7,4); tmp7=_mm_slli_si128(tmp7,12); tmp3=_mm_xor_si128(tmp3,tmp7);
    tmp2=_mm_srli_epi32(tmp3,1); tmp4=_mm_srli_epi32(tmp3,2); tmp5=_mm_srli_epi32(tmp3,7);
    tmp2=_mm_xor_si128(tmp2,tmp4); tmp2=_mm_xor_si128(tmp2,tmp5); tmp2=_mm_xor_si128(tmp2,tmp8);
    tmp3=_mm_xor_si128(tmp3,tmp2); tmp6=_mm_xor_si128(tmp6,tmp3); return tmp6;
