static uint8_t *counters, *ks, *pt, *ct;
static int nblocks;
static EVP_CIPHER_CTX *ctxs[NTHREADS];
static pthread_t th[NTHREADS];
static pthread_mutex_t mu = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cv_go = PTHREAD_COND_INITIALIZER;
static pthread_cond_t cv_done = PTHREAD_COND_INITIALIZER;
static int go_epoch = 0;
static int done_count = 0;
static int stop = 0;

typedef struct { int tid; int start; int end; } job_t;
static job_t jobs[NTHREADS];

static void *worker(void *arg) {
    int tid = (int)(intptr_t)arg;
    int seen = 0;
    for (;;) {
        pthread_mutex_lock(&mu);
        while (go_epoch == seen && !stop) pthread_cond_wait(&cv_go, &mu);
        if (stop) { pthread_mutex_unlock(&mu); break; }
        seen = go_epoch;
        pthread_mutex_unlock(&mu);
        int outlen = 0;
        EVP_EncryptUpdate(ctxs[tid], ks + jobs[tid].start*16, &outlen,
                          counters + jobs[tid].start*16, (jobs[tid].end-jobs[tid].start)*16);
        /* xor */
        uint8_t *k = ks + jobs[tid].start*16;
        uint8_t *p = pt + jobs[tid].start*16;
        uint8_t *c = ct + jobs[tid].start*16;
        size_t n = (jobs[tid].end-jobs[tid].start)*16;
        /* 16-byte xor via size_t */
        size_t i=0;
        for (; i+8<=n; i+=8) {
            uint64_t x = *(uint64_t*)(p+i) ^ *(uint64_t*)(k+i);
            *(uint64_t*)(c+i) = x;
        }
        pthread_mutex_lock(&mu);
        done_count++;
        if (done_count == NTHREADS) pthread_cond_signal(&cv_done);
        pthread_mutex_unlock(&mu);
    }
    return NULL;
}

static void run_once() {
    pthread_mutex_lock(&mu);
    done_count = 0;
    go_epoch++;
    pthread_cond_broadcast(&cv_go);
    while (done_count < NTHREADS) pthread_cond_wait(&cv_done, &mu);
    pthread_mutex_unlock(&mu);
}

int main() {
    nblocks = 60000*1024/16;
    counters = aligned_alloc(64, (size_t)nblocks*16);
    ks = aligned_alloc(64, (size_t)nblocks*16);
    pt = aligned_alloc(64, (size_t)nblocks*16);
    ct = aligned_alloc(64, (size_t)nblocks*16);
    uint8_t key[16], nonce[12];
    FILE *f=fopen("/dev/urandom","rb");
