    for (int i=0;i<nblocks;i++) {
        uint8_t *b=counters+(size_t)i*16;
        memcpy(b, nonce, 12);
        uint32_t c=i+2;
        b[12]=c>>24; b[13]=c>>16; b[14]=c>>8; b[15]=c;
    }
    for (int i=0;i<NTHREADS;i++) {
        ctxs[i]=EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(ctxs[i], EVP_aes_128_ecb(), NULL, key, NULL);
        EVP_CIPHER_CTX_set_padding(ctxs[i], 0);
        int chunk=nblocks/NTHREADS;
        jobs[i].tid=i;
        jobs[i].start=i*chunk;
        jobs[i].end=(i==NTHREADS-1)?nblocks:(i+1)*chunk;
        pthread_create(&th[i], NULL, worker, (void*)(intptr_t)i);
    }
    run_once(); /* warmup */
    struct timespec ts0, ts1;
    int reps=5;
    clock_gettime(CLOCK_MONOTONIC,&ts0);
    for(int r=0;r<reps;r++) run_once();
    clock_gettime(CLOCK_MONOTONIC,&ts1);
    double ms=(ts1.tv_sec-ts0.tv_sec)*1000.0+(ts1.tv_nsec-ts0.tv_nsec)/1e6;
    printf("pool ECB+xor: %.2f ms sink %u\n", ms/reps, ct[0]);
    pthread_mutex_lock(&mu); stop=1; go_epoch++; pthread_cond_broadcast(&cv_go); pthread_mutex_unlock(&mu);
    for(int i=0;i<NTHREADS;i++) pthread_join(th[i], NULL);
    return 0;
}
