static __m128i rk_g[11];
static __m128i nt_g, Hp_g[9];
static const uint8_t *src_g;
static uint8_t *dst_g;
static size_t starts[NTHREADS], counts[NTHREADS];
static uint32_t ctrs[NTHREADS];
static __m128i partials[NTHREADS];

static pthread_mutex_t mu = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cv_go = PTHREAD_COND_INITIALIZER;
static pthread_cond_t cv_done = PTHREAD_COND_INITIALIZER;
static int go_epoch=0, done_count=0, stop=0;

static void *worker(void *arg) {
    int tid=(int)(intptr_t)arg;
    int seen=0;
    for(;;){
        pthread_mutex_lock(&mu);
        while(go_epoch==seen && !stop) pthread_cond_wait(&cv_go,&mu);
        if(stop){ pthread_mutex_unlock(&mu); return NULL; }
        seen=go_epoch;
        pthread_mutex_unlock(&mu);
        partials[tid]=fused(rk_g, nt_g, ctrs[tid], src_g+starts[tid]*16, dst_g+starts[tid]*16, counts[tid], Hp_g);
        pthread_mutex_lock(&mu);
        done_count++;
        if(done_count==NTHREADS) pthread_cond_signal(&cv_done);
        pthread_mutex_unlock(&mu);
    }
}

int main(){
    size_t n=60000ull*1024; size_t nblocks=n/16;
    uint8_t *src=aligned_alloc(64,n);
    uint8_t *dst=aligned_alloc(64,n);
    uint8_t key[16], nonce[12];
    FILE *f=fopen("/dev/urandom","rb"); fread(src,1,n,f); fread(key,1,16,f); fread(nonce,1,12,f); fclose(f);
    rk_g[0]=_mm_loadu_si128((const __m128i*)key);
    #define EXP(i,rcon) do{ __m128i keygen=_mm_aeskeygenassist_si128(rk_g[i-1], rcon); keygen=_mm_shuffle_epi32(keygen,0xff); __m128i k=rk_g[i-1]; k=_mm_xor_si128(k,_mm_slli_si128(k,4)); k=_mm_xor_si128(k,_mm_slli_si128(k,4)); k=_mm_xor_si128(k,_mm_slli_si128(k,4)); rk_g[i]=_mm_xor_si128(k,keygen);}while(0)
    EXP(1,0x01);EXP(2,0x02);EXP(3,0x04);EXP(4,0x08);EXP(5,0x10);EXP(6,0x20);EXP(7,0x40);EXP(8,0x80);EXP(9,0x1b);EXP(10,0x36);
    uint8_t nt[16]={0}; memcpy(nt,nonce,12); nt_g=_mm_loadu_si128((__m128i*)nt);
    /* H */
    __m128i H=_mm_xor_si128(_mm_setzero_si128(), rk_g[0]);
    for(int r=1;r<10;r++) H=_mm_aesenc_si128(H, rk_g[r]);
    H=_mm_aesenclast_si128(H, rk_g[10]);
    __m128i Hs=bswap16(H);
    Hp_g[1]=Hs;
    for(int i=2;i<=8;i++){ prod_t p=clmul_full(Hp_g[i-1], Hs); Hp_g[i]=reduce(p.lo,p.hi); }
    size_t chunk=(nblocks/NTHREADS)&~7ull;
    src_g=src; dst_g=dst;
    pthread_t th[NTHREADS];
    for(int i=0;i<NTHREADS;i++){
        starts[i]=i*chunk;
        counts[i]=(i==NTHREADS-1)? nblocks-i*chunk : chunk;
        ctrs[i]=2+(uint32_t)starts[i];
        pthread_create(&th[i], NULL, worker, (void*)(intptr_t)i);
    }
    void run(){}
    #define RUN() do{ pthread_mutex_lock(&mu); done_count=0; go_epoch++; pthread_cond_broadcast(&cv_go); while(done_count<NTHREADS) pthread_cond_wait(&cv_done,&mu); pthread_mutex_unlock(&mu);}while(0)
    RUN();
    struct timespec ts0,ts1; int reps=5;
    clock_gettime(CLOCK_MONOTONIC,&ts0);
    for(int r=0;r<reps;r++) RUN();
    clock_gettime(CLOCK_MONOTONIC,&ts1);
    double ms=(ts1.tv_sec-ts0.tv_sec)*1000.0+(ts1.tv_nsec-ts0.tv_nsec)/1e6;
    printf("fused pool: %.2f ms sink %u\n", ms/reps, dst[0]);
    pthread_mutex_lock(&mu); stop=1; go_epoch++; pthread_cond_broadcast(&cv_go); pthread_mutex_unlock(&mu);
    for(int i=0;i<NTHREADS;i++) pthread_join(th[i],NULL);
    return 0;
}
