/* Gueron-Kounavis reduction, variant that works on the (lo,hi) product in our layout.
   From "Intel Carry-Less Multiplication Instruction and its Usage for Computing the GCM Mode" 
   Algorithm 3, adapted. We'll test against reduce(). */
static inline __m128i reduce_gk(__m128i X0, __m128i X1) {
    /* poly = x^128 + x^7 + x^2 + x + 1 reflected = 0xe1 << 120 in the other convention.
       A widely used implementation (cryptogams / bearssl style) for the bit-reflected
       product where lo/hi are our clmul_full outputs after the <<1 shift of the classic
       algorithm... Let's just time the existing reduce vs a shorter one and verify. */
    const __m128i poly = _mm_setr_epi32(0x1, 0, 0, 0xc2000000);
    __m128i t = _mm_clmulepi64_si128(X0, poly, 0x00);
    __m128i a = _mm_xor_si128(X0, _mm_slli_si128(t, 8));
    /* not complete */
    (void)X1; (void)a;
    return X0;
}

__attribute__((noinline))
static __m128i ghash8(const uint8_t *data, size_t nblocks, __m128i *Hp) {
    __m128i X=_mm_setzero_si128();
    size_t groups=nblocks/8;
    for (size_t g=0; g<groups; g++) {
        const uint8_t *p=data+g*128;
        __m128i c0=bswap16(_mm_loadu_si128((const __m128i*)(p+0)));
        __m128i c1=bswap16(_mm_loadu_si128((const __m128i*)(p+16)));
        __m128i c2=bswap16(_mm_loadu_si128((const __m128i*)(p+32)));
        __m128i c3=bswap16(_mm_loadu_si128((const __m128i*)(p+48)));
        __m128i c4=bswap16(_mm_loadu_si128((const __m128i*)(p+64)));
        __m128i c5=bswap16(_mm_loadu_si128((const __m128i*)(p+80)));
        __m128i c6=bswap16(_mm_loadu_si128((const __m128i*)(p+96)));
        __m128i c7=bswap16(_mm_loadu_si128((const __m128i*)(p+112)));
        prod_t px=clmul_full(X, Hp[8]);
        prod_t p0=clmul_full(c0, Hp[8]);
        prod_t p1=clmul_full(c1, Hp[7]);
        prod_t p2=clmul_full(c2, Hp[6]);
        prod_t p3=clmul_full(c3, Hp[5]);
        prod_t p4=clmul_full(c4, Hp[4]);
        prod_t p5=clmul_full(c5, Hp[3]);
        prod_t p6=clmul_full(c6, Hp[2]);
        prod_t p7=clmul_full(c7, Hp[1]);
        __m128i lo=px.lo, hi=px.hi;
        lo=_mm_xor_si128(lo,p0.lo); hi=_mm_xor_si128(hi,p0.hi);
        lo=_mm_xor_si128(lo,p1.lo); hi=_mm_xor_si128(hi,p1.hi);
        lo=_mm_xor_si128(lo,p2.lo); hi=_mm_xor_si128(hi,p2.hi);
        lo=_mm_xor_si128(lo,p3.lo); hi=_mm_xor_si128(hi,p3.hi);
        lo=_mm_xor_si128(lo,p4.lo); hi=_mm_xor_si128(hi,p4.hi);
        lo=_mm_xor_si128(lo,p5.lo); hi=_mm_xor_si128(hi,p5.hi);
        lo=_mm_xor_si128(lo,p6.lo); hi=_mm_xor_si128(hi,p6.hi);
        lo=_mm_xor_si128(lo,p7.lo); hi=_mm_xor_si128(hi,p7.hi);
        X=reduce(lo, hi);
    }
    return X;
}

int main(){
    size_t n=60000ull*1024; size_t nb=n/16;
    uint8_t *data=aligned_alloc(64,n);
    FILE *f=fopen("/dev/urandom","rb"); fread(data,1,n,f); fclose(f);
    uint8_t hb[16]; memset(hb, 0x5a, 16);
