        lo=_mm_xor_si128(lo,p2.lo); hi=_mm_xor_si128(hi,p2.hi);
        lo=_mm_xor_si128(lo,p3.lo); hi=_mm_xor_si128(hi,p3.hi);
        lo=_mm_xor_si128(lo,p4.lo); hi=_mm_xor_si128(hi,p4.hi);
